Here is a production-grade, type-safe `debounce` implementation in TypeScript. It preserves parameter types, handles execution contexts (`this`), and includes utilities to `cancel`, `flush`, and inspect `pending` state.

### Implementation

```typescript
export interface DebouncedFunction<T extends (...args: any[]) => any> {
  /**
   * Invokes the debounced function.
   */
  (this: ThisParameterType<T>, ...args: Parameters<T>): void;

  /**
   * Cancels any pending delayed invocation.
   */
  cancel: () => void;

  /**
   * Immediately invokes the pending execution, if any exists.
   */
  flush: () => void;

  /**
   * Returns true if there is a pending delayed invocation.
   */
  pending: () => boolean;
}

export interface DebounceOptions {
  /**
   * If true, triggers the function on the leading edge instead of the trailing edge.
   * Default: false
   */
  leading?: boolean;
}

/**
 * Creates a debounced function that delays invoking `fn` until after `delayMs`
 * milliseconds have elapsed since the last time the debounced function was invoked.
 *
 * @param fn - The function to debounce.
 * @param delayMs - The number of milliseconds to delay.
 * @param options - Configuration options (e.g. leading execution).
 * @returns A debounced wrapper with `cancel`, `flush`, and `pending` controls.
 */
export function debounce<T extends (...args: any[]) => any>(
  fn: T,
  delayMs: number,
  options: DebounceOptions = {}
): DebouncedFunction<T> {
  let timeoutId: ReturnType<typeof setTimeout> | undefined;
  let lastArgs: Parameters<T> | undefined;
  let lastThis: ThisParameterType<T> | undefined;
  const { leading = false } = options;

  const invoke = () => {
    if (lastArgs) {
      const args = lastArgs;
      const context = lastThis;
      lastArgs = undefined;
      lastThis = undefined;
      fn.apply(context, args);
    }
  };

  const cancel = () => {
    if (timeoutId !== undefined) {
      clearTimeout(timeoutId);
      timeoutId = undefined;
    }
    lastArgs = undefined;
    lastThis = undefined;
  };

  const flush = () => {
    if (timeoutId !== undefined) {
      clearTimeout(timeoutId);
      timeoutId = undefined;
      invoke();
    }
  };

  const pending = () => timeoutId !== undefined;

  const debounced = function (this: ThisParameterType<T>, ...args: Parameters<T>) {
    lastArgs = args;
    lastThis = this;

    const isLeadingCall = leading && timeoutId === undefined;

    if (timeoutId !== undefined) {
      clearTimeout(timeoutId);
    }

    timeoutId = setTimeout(() => {
      timeoutId = undefined;
      if (!leading) {
        invoke();
      }
    }, delayMs);

    if (isLeadingCall) {
      invoke();
    }
  };

  debounced.cancel = cancel;
  debounced.flush = flush;
  debounced.pending = pending;

  return debounced;
}
```

