### Usage Examples

#### 1. Standard TypeScript / DOM Usage

```typescript
function handleSearch(query: string, page: number): void {
  console.log(`Searching for "${query}" on page ${page}...`);
}

// Full type safety: Argument types and count are strictly checked
const debouncedSearch = debounce(handleSearch, 300);

debouncedSearch("react", 1); // Valid
// debouncedSearch(123, 1);  // Error: Argument of type 'number' is not assignable to 'string'

// Programmatic control:
if (debouncedSearch.pending()) {
  debouncedSearch.flush();  // Executes immediately
  // or debouncedSearch.cancel(); // Aborts execution
}
```

#### 2. React Hook Usage (`useDebouncedCallback`)

If using React, ensure the debounced instance persists across re-renders and auto-cleans on unmount:

```tsx
import { useEffect, useMemo, useRef } from "react";

export function useDebouncedCallback<T extends (...args: any[]) => any>(
  callback: T,
  delayMs: number,
  options?: DebounceOptions
): DebouncedFunction<T> {
  const callbackRef = useRef(callback);
  callbackRef.current = callback;

  const debounced = useMemo(() => {
    return debounce(
      ((...args: Parameters<T>) => {
        return callbackRef.current(...args);
      }) as T,
      delayMs,
      options
    );
  }, [delayMs, options?.leading]);

  useEffect(() => {
    return () => {
      debounced.cancel(); // Prevent memory leaks and state updates on unmounted components
    };
  }, [debounced]);

  return debounced;
}
```

Here is a production-ready, type-safe `debounce` implementation in TypeScript. It supports execution context (`this`), dynamic arguments, a `cancel()` method, and an optional `flush()` method.

### Implementation

```typescript
/**
 * Options to configure the debounce behavior.
 */
export interface DebounceOptions {
  /**
   * If `true`, trigger the function on the leading edge (immediately)
   * instead of the trailing edge. Default is `false`.
   */
  leading?: boolean;
}

/**
 * The debounced procedure interface containing utility methods.
 */
export type DebouncedFunction<T extends (...args: any[]) => any> = {
  (...args: Parameters<T>): void;
  /** Cancels any pending execution. */
  cancel: () => void;
  /** Immediately executes any pending execution. */
  flush: () => void;
  /** Checks if there is a pending execution. */
  isPending: () => boolean;
};

/**
 * Creates a debounced function that delays invoking `func` until after `wait`
 * milliseconds have elapsed since the last time the debounced function was invoked.
 *
 * @param func - The function to debounce.
 * @param wait - The number of milliseconds to delay.
 * @param options - Configuration options.
 */
export function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number,
  options: DebounceOptions = {}
): DebouncedFunction<T> {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  let lastArgs: Parameters<T> | null = null;
  let lastThis: ThisParameterType<T> | null = null;

  const { leading = false } = options;

  function invoke(): void {
    if (lastArgs !== null) {
      func.apply(lastThis, lastArgs);
      lastArgs = null;
      lastThis = null;
    }
  }

  function clearTimer(): void {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  }

  const debounced = function (this: ThisParameterType<T>, ...args: Parameters<T>): void {
    lastArgs = args;
    // eslint-disable-next-line @typescript-eslint/no-this-alias
    lastThis = this;

    const isFirstCall = timeoutId === null;

    clearTimer();

    if (leading && isFirstCall) {
      invoke();
    }

    timeoutId = setTimeout(() => {
      // If leading was triggered, do not trigger again on trailing edge
      // unless it was invoked multiple times during the wait window.
      if (!leading || lastArgs !== null) {
        invoke();
      }
      clearTimer();
    }, wait);
  } as DebouncedFunction<T>;

  debounced.cancel = (): void => {
    clearTimer();
    lastArgs = null;
    lastThis = null;
  };

  debounced.flush = (): void => {
    if (timeoutId !== null) {
      invoke();
      clearTimer();
    }
  };

  debounced.isPending = (): boolean => {
    return timeoutId !== null;
  };

  return debounced;
}
```

---

### Usage Examples

#### 1. Basic Usage (e.g., Search Input)

```typescript
function search(query: string, page: number): void {
  console.log(`Searching for "${query}" on page ${page}`);
}

// Inferred as: DebouncedFunction<(query: string, page: number) => void>
const debouncedSearch = debounce(search, 300);

// Calls will only execute the last one after 300ms
debouncedSearch("type", 1);
debouncedSearch("typesc", 1);
debouncedSearch("typescript", 1);

// Canceling pending calls (e.g., when a component unmounts)
// debouncedSearch.cancel();

// Force executing immediately if pending
// debouncedSearch.flush();
```

#### 2. React Hook Integration

```tsx
import React, { useEffect, useMemo, useState } from "react";

export function SearchComponent() {
  const [query, setQuery] = useState("");

  const debouncedFetch = useMemo(
    () =>
      debounce((searchTerm: string) => {
        // API call here
        console.log("Fetching API for:", searchTerm);
      }, 400),
    []
  );

  useEffect(() => {
    // Clean up timers on component unmount
    return () => {
      debouncedFetch.cancel();
    };
  }, [debouncedFetch]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setQuery(value);
    debouncedFetch(value);
  };

  return <input type="text" value={query} onChange={handleChange} />;
}
```

### Key Technical Details

- **Cross-Environment Timers**: Uses `ReturnType<typeof setTimeout>` instead of `number` or `NodeJS.Timeout`, making it compatible with both Node.js and the Browser.
- **Strict Parameter Preservation**: Uses `Parameters<T>` to ensure full type-checking on arguments passed to the debounced function.
- **Context Binding**: Preserves `this` using `ThisParameterType<T>` for classes or objects.

To reverse a string in TypeScript, the most robust approach is to convert the string into an array of characters, reverse the array, and join it back together.

### The Implementation

```typescript
/**
 * Reverses a given string.
 * Uses the spread operator to correctly handle Unicode characters (emojis, etc).
 */
export const reverseString = (str: string): string => {
  if (!str) return str;

  // Using the spread operator [...] handles surrogate pairs (emojis) 
  // better than .split('')
  return [...str].reverse().join('');
};

// --- Examples ---
console.log(reverseString("hello"));    // "olleh"
console.log(reverseString("TypeScript")); // "tpircSepyT"
console.log(reverseString("🚀hi"));      // "ih🚀"
```

### Why this approach?

1.  **Unicode Support:** Using `[...str]` (the spread operator) is safer than `str.split('')`. The `split` method can break multi-byte characters (like emojis or complex scripts) because it splits by UTF-16 code units. The spread operator iterates by code points, ensuring characters like `🚀` remain intact.
2.  **Type Safety:** The function explicitly defines the input as `string` and the return type as `string`, preventing runtime errors.
3.  **Immutability:** This approach does not mutate the original string (which is impossible in JS/TS anyway) and creates a clean, new string.
4.  **Edge Case Handling:** The `if (!str)` check handles empty strings or `null`/`undefined` (if strict null checks are off) gracefully.

### Performance Note
For extremely large strings (megabytes in size), creating an array can be memory-intensive. However, for standard UI development and general-purpose programming, this approach is the industry standard for readability and correctness.
